(window.DETAIL_C = window.DETAIL_C || {})["phy-12-13"] = {"phy-12-13-m01":{"idea":"A 50 Hz current goes through 50 full cycles each second, and reverses twice per cycle.","steps":["The mains frequency in India is 50 Hz.","In each cycle the current flows once one way and once the other way.","So it reverses 2 × 50 = 100 times each second."],"others":"60 Hz is the US mains. 100 Hz is not the Indian frequency. Reversing only 50 times a second forgets that each cycle has two reversals.","trap":"Reversals per second are twice the frequency.","answer":"50 Hz, so the direction of the current reverses 100 times each second"},"phy-12-13-m02":{"idea":"The rms value of a sine wave is the peak divided by √2.","steps":["rms is the square root of the mean of i² over a cycle.","The mean of sin² is 1/2.","So I_rms = I₀/√2 ≈ 0.707 I₀."],"others":"2I₀/π is the half-cycle average. √2 I₀ goes the wrong way. I₀/2 would use the mean instead of the root of the mean square.","trap":"rms = peak × 0.707.","answer":"I₀/√2, which is about 0.707 I₀"},"phy-12-13-m03":{"idea":"Household ratings are rms values, so the peak is √2 times larger.","steps":["V₀ = √2 × V_rms.","V₀ = 1.414 × 230.","V₀ ≈ 325 V."],"others":"230 V is the rms value itself. 163 V divides by √2 instead of multiplying. 460 V doubles it.","trap":"Meters and labels show rms.","answer":"325 V"},"phy-12-13-m04":{"idea":"Over a full cycle the positive and negative halves cancel.","steps":["The two half cycles have equal areas.","One is positive and the other negative.","So the average over a full cycle is zero."],"others":"The peak and 0.707 of it are not averages. 0.637 of the peak is the half-cycle average only.","trap":"Average over half a cycle: 0.637 I₀. Over a full cycle: 0.","answer":"zero, because the positive and negative half cycles cancel"},"phy-12-13-m05":{"idea":"In a pure resistor, current and voltage rise and fall together.","steps":["By Ohm's law, i = v/R at every instant.","So the current is zero when the voltage is zero.","They reach their peaks together: in phase."],"others":"180° or 90° phase differences belong to other elements, not to a resistor.","trap":"Resistor: in phase.","answer":"are in phase with each other"},"phy-12-13-m06":{"idea":"In a pure inductor, the current lags the voltage by 90°.","steps":["The voltage across an inductor is L di/dt.","It is largest when the current changes fastest, which is a quarter cycle before the current peak.","So the current lags by 90°."],"others":"180° lag and in-phase do not fit an inductor. Leading by 90° is for a capacitor.","trap":"ELI: voltage (E) leads current (I) in an inductor (L).","answer":"lags behind the voltage by 90°"},"phy-12-13-m07":{"idea":"In a pure capacitor, the current leads the voltage by 90°.","steps":["i = dq/dt = C dv/dt.","The current is largest when the voltage passes through zero, a quarter cycle before the voltage peak.","So the current leads by 90°."],"others":"Lagging by 90° is the inductor. 180° lead and in-phase are not correct for a capacitor.","trap":"ICE: current (I) leads voltage (E) in a capacitor (C).","answer":"leads the voltage by 90°"},"phy-12-13-m08":{"idea":"Reactance is opposition to AC, measured in ohms.","steps":["X_L = ωL has the unit of ohm.","It grows with frequency.","For steady DC, ω = 0 so X_L = 0."],"others":"Henry is the unit of inductance. Farad is for capacitance. X_L does not fall with frequency.","trap":"Reactance is in ohm, like resistance.","answer":"ohm, and it increases when the frequency increases"},"phy-12-13-m09":{"idea":"A capacitor blocks DC but passes high-frequency AC more easily.","steps":["X_C = 1/(ωC).","For DC, ω = 0 and X_C is infinite.","At high frequency X_C is much smaller, so more current passes."],"others":"X_C does not rise with frequency. It is not the same for DC and AC. The last option is true for DC but wrong for AC: X_C falls at high frequency, not becomes infinite.","trap":"Capacitor: blocks DC, passes AC.","answer":"much smaller, because X_C = 1/ωC falls as ω rises"},"phy-12-13-m10":{"idea":"Inductive reactance grows with frequency and capacitive reactance falls.","steps":["X_L = ωL ∝ f, so it doubles.","X_C = 1/(ωC) ∝ 1/f, so it halves."],"others":"The other options swap or treat both the same way.","trap":"Opposite behaviours.","answer":"X_L becomes twice as large, and X_C becomes half as large"},"phy-12-13-m11":{"idea":"In a series LCR circuit the inductor and capacitor voltages point in opposite directions on the phasor diagram.","steps":["V_R is in phase with the current.","V_L leads by 90° and V_C lags by 90°, so they oppose each other.","Combine: Z = √(R² + (X_L − X_C)²)."],"others":"Adding X_L and X_C ignores that they oppose. A plain sum R + X_L + X_C ignores the phases. The last form drops the square root.","trap":"Subtract the reactances, then use Pythagoras.","answer":"Z = √(R² + (X_L − X_C)²)"},"phy-12-13-m12":{"idea":"When X_L is larger than X_C the circuit acts inductive, and the voltage leads the current.","steps":["tan φ = (X_L − X_C)/R is positive.","So the source voltage leads the current.","The circuit behaves like a resistor with an inductor."],"others":"Leading with a capacitive behaviour contradicts the sign. Lagging would need X_C larger. In phase is only at resonance.","trap":"If X_C were larger, the current would lead.","answer":"leads the current in phase, and the circuit behaves as an inductive one"},"phy-12-13-m13":{"idea":"A pure inductor has a power factor of zero.","steps":["Power factor = cos φ.","For a pure inductor φ = 90°, so cos φ = 0.","It takes energy in one quarter cycle and returns it in the next, so the average power is zero."],"others":"0.5, one and infinity do not match φ = 90°.","trap":"cos 90° = 0.","answer":"zero, since the current lags the voltage by 90°"},"phy-12-13-m14":{"idea":"A current that does no net work is called wattless.","steps":["In a pure inductor or capacitor, current and voltage are 90° apart.","P = V I cos 90° = 0.","So the current does no net work: it is wattless."],"others":"Eddy, leakage and peak currents are different ideas.","trap":"Wattless = zero average power.","answer":"wattless current, as in a pure inductor or capacitor"},"phy-12-13-m15":{"idea":"At resonance the reactances cancel, so the impedance is the lowest.","steps":["At resonance X_L = X_C.","So Z = R, which is the smallest possible value.","The current is then the greatest."],"others":"X_L = R is not the resonance condition. The impedance is not the greatest at resonance in a series circuit.","trap":"Series resonance: minimum impedance, maximum current.","answer":"X_L = X_C, the impedance is the least and equal to R"},"phy-12-13-m16":{"idea":"At resonance the voltages across L and C are equal and opposite.","steps":["The same current flows through L and C.","With X_L = X_C, their voltages have equal size.","One leads by 90° and the other lags by 90°, so they are 180° apart and cancel."],"others":"Same phase would add, which is not the case. They are not zero. They are not different in size.","trap":"Each can be much larger than the source voltage.","answer":"equal in size and opposite in phase, so they cancel each other"},"phy-12-13-m17":{"idea":"Resonant frequency goes as 1/√C.","steps":["f = 1/(2π√(LC)).","C becomes 4C, so √C becomes 2√C.","f becomes half."],"others":"Twice or four times would need C to fall. A quarter would need f ∝ 1/C.","trap":"Square root: ×4 in C gives ÷2 in f.","answer":"half of the original"},"phy-12-13-m18":{"idea":"Less resistance means a sharper, taller resonance and a bigger Q.","steps":["Q = ω₀L/R, so a smaller R gives a larger Q.","The peak current V/R is higher.","The curve is narrower, so the circuit picks out one frequency better."],"others":"Q is not the same when R changes. A smaller Q goes with a larger R and a flatter curve.","trap":"Low R: high Q, sharp tuning.","answer":"a larger Q factor and a sharper resonance"},"phy-12-13-m19":{"idea":"A choke limits AC with reactance instead of resistance, so it wastes almost no energy.","steps":["A choke has a large inductance and very small resistance.","It limits the current by its reactance.","The power factor is nearly zero, so the average power loss is very small."],"others":"It does not block AC and pass DC. It does not increase current. A power factor of one would mean it behaves like a resistor and wastes power.","trap":"A series resistor would waste I²R as heat.","answer":"reduces the current without much loss of energy as heat"},"phy-12-13-m20":{"idea":"A parallel LC circuit has the largest impedance at resonance.","steps":["At resonance the currents in the two branches are equal and opposite.","Very little is drawn from the source.","So the impedance is the largest and the current from the source is the least."],"others":"The least impedance with the largest current is the series behaviour. Mixed forms do not match.","trap":"Parallel circuit rejects its resonant frequency.","answer":"the largest, and the current drawn from the source is the least"},"phy-12-13-m21":{"idea":"In an LC circuit the energy swings between the capacitor and the inductor.","steps":["When the capacitor is fully discharged, the charge is zero and the electric energy is zero.","The current is at its maximum.","So all the energy is stored as ½LI² in the magnetic field."],"others":"The total energy is not zero. It is not all in the capacitor. It is not shared equally at this instant.","trap":"Zero charge means maximum current.","answer":"all in the magnetic field of the inductor"},"phy-12-13-m22":{"idea":"The rms value is the steady current that gives the same heating.","steps":["The mean power in the resistor is I₀²R/2.","A steady current gives I_dc²R.","Equal heat: I_dc = I₀/√2."],"others":"I₀ and I₀/2 do not give the same heat. 2I₀/π is the half-cycle average, not the heating equivalent.","trap":"rms is defined by heating.","answer":"I_dc = I₀/√2"},"phy-12-13-m23":{"idea":"Only the part of the voltage in phase with the current does net work.","steps":["P = V_rms I_rms cos φ.","cos φ = R/Z, so P = I_rms² Z (R/Z) = I_rms² R.","The power is all lost in the resistor."],"others":"sin φ would give the reactive part. V_rms I_rms alone ignores the phase. Using peak values with cos φ gives twice the true power.","trap":"Use rms values.","answer":"V_rms I_rms cos φ, which is I_rms² R"},"phy-12-13-m24":{"idea":"As the frequency rises, X_L rises, so the phase angle grows and the power factor falls.","steps":["cos φ = R/√(R² + ω²L²).","A larger ω makes the denominator larger.","So cos φ decreases."],"others":"Increasing power factor or leaving it the same does not match the formula. The impedance increases, not decreases.","trap":"At very high frequency the circuit is nearly a pure inductor.","answer":"decreases, because the phase angle increases"},"phy-12-13-n01":{"idea":"rms value of AC is the peak over √2.","steps":["I_rms = I₀/√2.","I₀ = 5.0 A.","I_rms = 5.0/1.414 = 3.54 A."],"trap":"rms is always smaller than the peak.","answer":"3.54 A"},"phy-12-13-n02":{"idea":"Inductive reactance is X_L = 2πfL.","steps":["ω = 2π × 50 = 314.16 rad/s.","X_L = ωL = 314.16 × 0.10.","X_L = 31.42 Ω."],"trap":"Use 2π f, not just f.","answer":"31.42 Ω"},"phy-12-13-n03":{"idea":"Capacitive reactance is X_C = 1/(2πfC).","steps":["ω = 2π × 50 = 314.16 rad/s.","ωC = 314.16 × 50 × 10⁻⁶ = 0.015708.","X_C = 1/0.015708 = 63.66 Ω."],"trap":"Convert μF to F.","answer":"63.66 Ω"},"phy-12-13-n04":{"idea":"Impedance of a series LCR circuit uses R and the difference of reactances.","steps":["X_L = ωL = 500 × 0.10 = 50 Ω.","X_C = 1/(ωC) = 1/(500 × 100 × 10⁻⁶) = 20 Ω.","Z = √(40² + (50 − 20)²) = √(1600 + 900).","Z = 50 Ω."],"trap":"Subtract X_C from X_L before squaring.","answer":"50 Ω"},"phy-12-13-n05":{"idea":"Current is the rms voltage divided by the impedance.","steps":["Z = 50 Ω (from the previous question).","I_rms = V_rms/Z = 200/50.","I_rms = 4.0 A."],"trap":"Use rms voltage to get rms current.","answer":"4.0 A"},"phy-12-13-n06":{"idea":"The phase angle comes from tan φ = (X_L − X_C)/R.","steps":["X_L − X_C = 50 − 20 = 30 Ω.","tan φ = 30/40 = 0.75.","φ = tan⁻¹ 0.75 = 36.87°."],"trap":"Check: cos φ = R/Z = 40/50 = 0.8.","answer":"36.87°"},"phy-12-13-n07":{"idea":"Average power is V_rms I_rms cos φ.","steps":["I_rms = 4 A and cos φ = R/Z = 0.8.","P = 200 × 4 × 0.8.","P = 640 W."],"trap":"Check: I²R = 16 × 40 = 640 W.","answer":"640 W"},"phy-12-13-n08":{"idea":"Resonant frequency is f = 1/(2π√(LC)).","steps":["LC = 0.10 × 10 × 10⁻⁶ = 10⁻⁶.","√(LC) = 10⁻³.","f = 1/(2π × 10⁻³) = 159.15 Hz."],"trap":"Convert μF to F.","answer":"159.15 Hz"},"phy-12-13-n09":{"idea":"The current is greatest at resonance, where Z = R.","steps":["At resonance, the reactances cancel, so Z = R = 20 Ω.","I = V/R = 100/20.","I = 5.0 A."],"trap":"Any other frequency gives a smaller current.","answer":"5.0 A"},"phy-12-13-n10":{"idea":"The Q factor is Q = ω₀L/R.","steps":["ω₀ = 1/√(LC) = 1/√(0.10 × 10 × 10⁻⁶) = 1000 rad/s.","Q = ω₀L/R = 1000 × 0.10/20 = 5, a pure number."],"trap":"Q is a pure number.","answer":"5"},"phy-12-13-n11":{"idea":"Average power in a resistor uses the rms current squared.","steps":["I_rms² = I₀²/2 = 16/2 = 8 A².","P = I_rms² R = 8 × 10.","P = 80 W."],"trap":"A steady 4 A would give 160 W, twice as much.","answer":"80 W"},"phy-12-13-n12":{"idea":"Peak voltage is √2 times the rms voltage.","steps":["V₀ = √2 × V_rms.","V₀ = 1.4142 × 230.","V₀ = 325.27 V."],"trap":"The peak is bigger than the rms.","answer":"325.27 V"},"phy-12-13-n13":{"idea":"An LC circuit oscillates at f = 1/(2π√(LC)).","steps":["L = 2.0 × 10⁻³ H and C = 5.0 × 10⁻⁶ F.","LC = 10⁻⁸, so √(LC) = 10⁻⁴.","f = 1/(2π × 10⁻⁴) = 1591.5 Hz."],"trap":"Convert mH and μF to H and F.","answer":"1591.5 Hz"}};
